:root {
  --color-bg: #1a1a2e;
  --color-card: #16213e;
  --color-accent: #e94560;
  --color-text: #eaeaea;
  --color-text-muted: #a0a0b0;
  --color-coin: #f5c542;
  --color-coin-dark: #c49a1a;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--color-bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.game-card {
  background: var(--color-card);
  border-radius: 16px;
  padding: 32px 24px;
  max-width: 400px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.coin-container {
  width: 128px;
  height: 128px;
  display: flex;
  align-items: center;
  justify-content: center;
  image-rendering: pixelated;
}

canvas {
  width: 128px;
  height: 128px;
  image-rendering: pixelated;
  transition: transform 0.15s ease;
}

canvas.flipping {
  animation: flipAnim 0.4s ease;
}

@keyframes flipAnim {
  0% { transform: scaleX(1); }
  25% { transform: scaleX(0.6); }
  50% { transform: scaleX(0.1); }
  75% { transform: scaleX(0.6); }
  100% { transform: scaleX(1); }
}

.stats {
  display: flex;
  gap: 16px;
  width: 100%;
  justify-content: center;
  flex-wrap: wrap;
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  min-width: 72px;
}

.stat-label {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.stat-value {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-coin);
}

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
  flex-wrap: wrap;
  justify-content: center;
}

.btn {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 28px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
  min-width: 120px;
}

.btn.primary {
  background: var(--color-accent);
  color: #fff;
}

.btn.primary:hover {
  background: #f05a75;
  box-shadow: 0 0 12px rgba(233, 69, 96, 0.5);
}

.btn.primary:active {
  transform: scale(0.96);
}

.btn.secondary {
  background: transparent;
  color: var(--color-text);
  border: 2px solid var(--color-text-muted);
}

.btn.secondary:hover {
  border-color: var(--color-text);
  background: rgba(255, 255, 255, 0.05);
}

.btn.secondary:active {
  transform: scale(0.96);
}

.btn:focus-visible {
  outline: 3px solid var(--color-coin);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (max-width: 400px) {
  .game-card {
    padding: 24px 16px;
  }
  .stat {
    min-width: 60px;
  }
  .stat-value {
    font-size: 1.5rem;
  }
  .btn {
    min-width: 100px;
    padding: 10px 20px;
  }
}

(function() {
  'use strict';

  const canvas = document.getElementById('coinCanvas');
  const ctx = canvas.getContext('2d');
  const headsCountEl = document.getElementById('headsCount');
  const tailsCountEl = document.getElementById('tailsCount');
  const streakCountEl = document.getElementById('streakCount');
  const flipBtn = document.getElementById('flipBtn');
  const resetBtn = document.getElementById('resetBtn');
  const statusMessage = document.getElementById('statusMessage');

  let heads = 0;
  let tails = 0;
  let currentStreak = 0;
  let lastSide = null;
  let isFlipping = false;

  // Pixel size for drawing
  const PX = 8;

  function drawCoin(side) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const cx = 64, cy = 64, r = 56;

    // Base coin circle
    ctx.fillStyle = '#f5c542';
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.fill();

    // Inner ring
    ctx.strokeStyle = '#c49a1a';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(cx, cy, r - 8, 0, Math.PI * 2);
    ctx.stroke();

    if (side === 'heads') {
      // Draw a simple pixel face
      ctx.fillStyle = '#c49a1a';
      // Eyes
      ctx.fillRect(cx - 20, cy - 16, PX, PX);
      ctx.fillRect(cx + 12, cy - 16, PX, PX);
      // Mouth (smile)
      ctx.fillRect(cx - 12, cy + 8, PX, PX);
      ctx.fillRect(cx - 4, cy + 16, PX, PX);
      ctx.fillRect(cx + 4, cy + 16, PX, PX);
      ctx.fillRect(cx + 12, cy + 8, PX, PX);
      // Nose
      ctx.fillRect(cx - 4, cy - 4, PX, PX);
    } else if (side === 'tails') {
      // Draw a simple pixel star
      ctx.fillStyle = '#c49a1a';
      // Vertical line
      ctx.fillRect(cx - 4, cy - 24, PX, 48);
      // Horizontal line
      ctx.fillRect(cx - 24, cy - 4, 48, PX);
      // Diagonal lines
      for (let i = 0; i < 4; i++) {
        ctx.fillRect(cx - 16 + i * 8, cy - 16 + i * 8, PX, PX);
        ctx.fillRect(cx + 16 - i * 8, cy - 16 + i * 8, PX, PX);
        ctx.fillRect(cx - 16 + i * 8, cy + 16 - i * 8, PX, PX);
        ctx.fillRect(cx + 16 - i * 8, cy + 16 - i * 8, PX, PX);
      }
    } else {
      // Idle state: draw a question mark
      ctx.fillStyle = '#c49a1a';
      ctx.font = 'bold 48px system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('?', cx, cy);
    }
  }

  function updateDisplay() {
    headsCountEl.textContent = heads;
    tailsCountEl.textContent = tails;
    streakCountEl.textContent = currentStreak;
  }

  function announce(msg) {
    statusMessage.textContent = msg;
  }

  function flip() {
    if (isFlipping) return;
    isFlipping = true;

    const result = Math.random() < 0.5 ? 'heads' : 'tails';

    // Update counters
    if (result === 'heads') {
      heads++;
    } else {
      tails++;
    }

    // Update streak
    if (lastSide === result) {
      currentStreak++;
    } else {
      currentStreak = 1;
    }
    lastSide = result;

    // Animate
    canvas.classList.add('flipping');

    // Draw result after half animation
    setTimeout(() => {
      drawCoin(result);
    }, 200);

    setTimeout(() => {
      canvas.classList.remove('flipping');
      updateDisplay();
      announce('Flipped: ' + result + '. Heads: ' + heads + ', Tails: ' + tails + ', Streak: ' + currentStreak);
      isFlipping = false;
    }, 400);
  }

  function reset() {
    if (isFlipping) return;
    heads = 0;
    tails = 0;
    currentStreak = 0;
    lastSide = null;
    updateDisplay();
    drawCoin(null);
    announce('Reset. All counters cleared.');
  }

  // Initial draw
  drawCoin(null);
  updateDisplay();

  flipBtn.addEventListener('click', flip);
  resetBtn.addEventListener('click', reset);
})();
